#include <vector>
#include <iostream>

int main() {
    std::vector<bool> flags(8, true);
    std::cout << "Size: " << flags.size() << std::endl;

    // Special API for bit manipulation
    flags.flip(); // Negates all elements (T -> F)

    // Access via Proxy Class (Concept B)
    flags[0].flip(); // Negates element at index 0 (F -> T)

    for (bool b : flags) {
        std::cout << (b ? 'T' : 'F');
    }
    std::cout << std::endl; // Output: TFFFFFFF
}
